;//========================================================================================// CTempMPSemaphore_AC//========================================================================================class EXPORT_AC CTempMPSemaphore_AC : public CMPSemaphore_AC{public:	CTempMPSemaphore_AC() : CMPSemaphore_AC() {}	CTempMPSemaphore_AC(MPSemaphoreCount maximumValue, MPSemaphoreCount initialValue = 1) : CMPSemaphore_AC(maximumValue, initialValue) {}	CTempMPSemaphore_AC(CMPSemaphore_AC& from) : CMPSemaphore_AC(from.release()) {}	~CTempMPSemaphore_AC()	{ reset(); }	void Create(MPSemaphoreCount maximumValue = 1, MPSemaphoreCount initialValue = 1)	{ reset(); CMPSemaphore_AC::Create(maximumValue, initialValue); }	CTempMPSemaphore_AC& operator=(CMPSemaphore_AC& rhs)	{ fIdentifier = rhs.release(); return *this; }};//========================================================================================// CMPCountedSemaphore_AC//========================================================================================class EXPORT_AC CMPCountedSemaphore_AC : public CMPSemaphore_AC// CMPCountedSemaphore_AC implements a counting semaphore with access to the count value. // Because MP semaphores don't provide access to the count, we have to maintain our// own count and keep it in sync. {public:	CMPCountedSemaphore_AC();	CMPCountedSemaphore_AC(MPSemaphoreCount maximumValue, MPSemaphoreCount initialValue = 1);	CMPCountedSemaphore_AC(const CMPCountedSemaphore_AC& from);	~CMPCountedSemaphore_AC() {}	void Create(MPSemaphoreCount maximumValue = 1, MPSemaphoreCount initialValue = 1);	void Delete();	bool Wait(Duration timeout);	void Signal();	void SignalOne();	void SignalAll();	CMPCountedSemaphore_AC& operator=(const CMPCountedSemaphore_AC& rhs);	MPSemaphoreCount GetCount() const	{ return fCount; }protected:	CTempMPMutex_AC		fCountLock;	MPSemaphoreCount	fCount;};//========================================================================================// CTempMPCountedSemaphore_AC//========================================================================================class EXPORT_AC CTempMPCountedSemaphore_AC : public CMPCountedSemaphore_AC{public:	CTempMPCountedSemaphore_AC() : CMPCountedSemaphore_AC() {}	CTempMPCountedSemaphore_AC(MPSemaphoreCount maximumValue, MPSemaphoreCount initialValue = 1) : CMPCountedSemaphore_AC(maximumValue, initialValue) {}	CTempMPCountedSemaphore_AC(CMPCountedSemaphore_AC& from);	~CTempMPCountedSemaphore_AC()	{ reset(); }	void Create(MPSemaphoreCount maximumValue = 1, MPSemaphoreCount initialValue = 1)	{ reset(); CMPCountedSemaphore_AC::Create(maximumValue, initialValue); }	CTempMPCountedSemaphore_AC& operator=(CMPCountedSemaphore_AC& rhs);};#endif // qWantsMP#endif // __CThreadServer__